INSERT INTO inventory_audit SELECT gen_random_uuid(),'manager','WAREHOUSE_MANAGER',date_trunc('day',now())-interval '1 day'+interval '2 hours','ADJUST','00000000-0000-0000-0000-000000000215',id,680,8,'seed-anomaly-215','DEMO: late-night stock correction following cycle count' FROM warehouses WHERE code='WH-PUN';
INSERT INTO inventory_audit SELECT gen_random_uuid(),'seed','SYSTEM',now()-(n||' days')::interval,'RECEIVE','00000000-0000-0000-0000-000000000110',id,200,200+n*5,'seed-history-'||n,'DEMO: historical receiving activity' FROM warehouses CROSS JOIN generate_series(1,7) n;
